<template><div><div class="page-title"><div><div class="eyebrow">AUTHORIZED DISCOVERY</div><h2>扫描任务</h2></div><el-button type="primary" @click="openCreate">创建扫描</el-button></div><el-alert title="仅允许对明确授权的实验环境执行扫描" type="warning" show-icon class="section-card"/><div v-loading="loading" class="table-wrap section-card"><el-table :data="scans"><el-table-column prop="task_name" label="名称"/><el-table-column prop="target" label="目标范围"/><el-table-column prop="status" label="状态"/><el-table-column prop="scan_type" label="类型"/><el-table-column prop="created_at" label="创建时间"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="detail(row)">详情</el-button><el-button link type="success" :disabled="row.status!=='pending'" @click="start(row)">启动</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!scans.length" description="暂无扫描任务"/></div><el-dialog v-model="createVisible" title="创建扫描任务" width="430px"><el-form :model="form" label-width="90px"><el-form-item label="任务名称"><el-input v-model="form.task_name"/></el-form-item><el-form-item label="目标"><el-input v-model="form.target" placeholder="仅填写已授权目标"/></el-form-item><el-form-item label="类型"><el-select v-model="form.scan_type"><el-option label="端口扫描" value="port_scan"/></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">创建</el-button></template></el-dialog><el-drawer v-model="detailVisible" title="扫描详情" size="520px"><el-descriptions v-if="selected" :column="1" border><el-descriptions-item label="名称">{{selected.task_name}}</el-descriptions-item><el-descriptions-item label="目标">{{selected.target}}</el-descriptions-item><el-descriptions-item label="状态">{{selected.status}}</el-descriptions-item><el-descriptions-item label="摘要">{{selected.result_summary||selected.error_message||'暂无结果'}}</el-descriptions-item></el-descriptions><el-divider/><el-table :data="results"><el-table-column prop="result_type" label="结果类型"/><el-table-column prop="normalized_data" label="解析结果"/></el-table></el-drawer></div></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from "vue"; import { ElMessage } from "element-plus"; import client from "../api/client"; import type { Scan, ScanResult } from "../api/types";
const scans=ref<Scan[]>([]),results=ref<ScanResult[]>([]),selected=ref<Scan|null>(null),loading=ref(true),saving=ref(false),createVisible=ref(false),detailVisible=ref(false);const form=reactive({task_name:"",target:"",scan_type:"port_scan"});
const load=async()=>{loading.value=true;try{scans.value=(await client.get("/scans")).data;}catch{scans.value=[];}finally{loading.value=false;}};const openCreate=()=>{Object.assign(form,{task_name:"",target:"",scan_type:"port_scan"});createVisible.value=true};const create=async()=>{saving.value=true;try{await client.post("/scans",form);ElMessage.success("扫描任务已创建");createVisible.value=false;load();}catch{ElMessage.error("创建失败，请确认目标已授权");}finally{saving.value=false;}};const start=async(s:Scan)=>{try{await client.post(`/scans/${s.id}/start`);ElMessage.success("扫描已启动");load();}catch{ElMessage.error("启动失败，请确认 Nmap 可用");}};const detail=async(s:Scan)=>{selected.value=(await client.get(`/scans/${s.id}`)).data;results.value=(await client.get(`/scans/${s.id}/results`)).data;detailVisible.value=true};onMounted(load);
</script>
